using System;
using System.Collections.Generic;
using System.Linq;
using System.Web.Script.Serialization;
using RogControl;

internal static class WindowsBrightnessTests {
 static int checks;
 static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}
 static Dictionary<string,object> Map(params object[] values){return WindowsBrightnessService.Object(values);}
 sealed class Fake:IWindowsBrightnessNative {
  internal BrightnessRawMonitor[] Monitors={new BrightnessRawMonitor{InstanceName="DISPLAY\\PRIVATE-SERIAL-A_0",FriendlyName="Synthetic panel",Active=true,Current=50,LevelCount=5,Levels=new[]{0,25,50,75,100}}};
  internal BrightnessRawMethod[] Methods={new BrightnessRawMethod{InstanceName="DISPLAY\\PRIVATE-SERIAL-A_0",Active=true}};
  internal int Reads,MethodReads,Writes;internal uint Code;internal bool ThrowSet,ThrowReadAfter,InvalidMethodResult;internal Action<Fake> OnRead,OnSet;
  public BrightnessRawMonitor[] ReadMonitors(){Reads++;if(ThrowReadAfter&&Writes>0)throw new Exception("PRIVATE-SERIAL-A");if(OnRead!=null)OnRead(this);return Monitors;}
  public BrightnessRawMethod[] ReadMethods(){MethodReads++;return Methods;}
  public uint SetBrightness(string instance,int value){Writes++;Check(instance=="DISPLAY\\PRIVATE-SERIAL-A_0","only exact paired provider instance is invoked");if(OnSet!=null)OnSet(this);else Monitors[0].Current=value;if(InvalidMethodResult)throw new WindowsBrightnessProtocolError("INVALID_METHOD_RESULT");if(ThrowSet)throw new Exception("PRIVATE-SERIAL-A");return Code;}
 }
 static WindowsBrightnessService Service(Fake fake,Func<long> clock=null){return new WindowsBrightnessService(fake,clock??(()=>0),()=>new DateTime(2026,10,14,12,0,0,DateTimeKind.Utc));}
 static Dictionary<string,object> Read(WindowsBrightnessService service){return service.Handle(Map("op","read"));}
 static Dictionary<string,object> Monitor(Dictionary<string,object> snapshot){return ((Dictionary<string,object>[])snapshot["monitors"]).Single();}
 static Dictionary<string,object> Request(Dictionary<string,object> snapshot,int value=75){var monitor=Monitor(snapshot);return Map("op","set","targetId",monitor["id"],"brightness",value,"sessionToken",snapshot["sessionToken"],"readToken",snapshot["readToken"],"currentFingerprint",monitor["fingerprint"],"experimental",true);}
 static void Rejected(Action action,string code){bool rejected=false;try{action();}catch(WindowsBrightnessProtocolError error){rejected=error.Code==code;}Check(rejected,"reject "+code);}
 static void ReadFacts(){var fake=new Fake();var service=Service(fake);Check(fake.Reads==0&&fake.Writes==0,"constructor is inert");var snapshot=Read(service);var monitor=Monitor(snapshot);Check((bool)monitor["supportsWrite"]&&(int)monitor["currentBrightness"]==50,"active unique instance + valid levels yields capability");Check(((int[])monitor["levels"]).SequenceEqual(new[]{0,25,50,75,100}),"only real provider levels returned");string output=new JavaScriptSerializer().Serialize(snapshot);Check(!output.Contains("PRIVATE-SERIAL")&&!output.Contains("DISPLAY")&&!output.Contains("InstanceName"),"public protocol never exposes raw monitor path/serial");Check(WindowsBrightnessRules.TargetId((string)monitor["id"])&&WindowsBrightnessRules.Token((string)snapshot["sessionToken"])&&WindowsBrightnessRules.Token((string)snapshot["readToken"]),"session-salted ID and opaque capture are validated");Check((string)Monitor(Read(Service(new Fake())))["id"]!=(string)monitor["id"],"another worker session cannot inherit raw identity hash");
  foreach(bool? active in new bool?[]{false,null}){fake=new Fake();fake.Monitors[0].Active=active;Check(((Dictionary<string,object>[])Read(Service(fake))["monitors"]).Length==0&&fake.Writes==0,"inactive/unknown monitor not inferred active");}
  fake=new Fake();fake.Monitors[0].Current=0;Check((int)Monitor(Read(Service(fake)))["currentBrightness"]==0,"real zero is preserved");fake=new Fake();fake.Monitors[0].FriendlyName="bad\nname";Check((string)Monitor(Read(Service(fake)))["name"]=="屏幕 1","invalid friendly text never exposes source path");
  foreach(int[] levels in new int[][]{null,new int[0],new[]{0,50,50,75,100},new[]{-1,25,50,75,100},new[]{0,25,50,75,101},new[]{0,25,75,100}}){fake=new Fake();fake.Monitors[0].Levels=levels;monitor=Monitor(Read(Service(fake)));Check(!(bool)monitor["supportsWrite"]&&monitor["currentBrightness"]==null&&((int[])monitor["levels"]).Length==0,"invalid levels disable rather than invent current or range");}
  foreach(int? count in new int?[]{null,0,4,6,102}){fake=new Fake();fake.Monitors[0].LevelCount=count;Check(!(bool)Monitor(Read(Service(fake)))["supportsWrite"],"level count must match array");}
  foreach(int? current in new int?[]{null,-1,1,101}){fake=new Fake();fake.Monitors[0].Current=current;Check(!(bool)Monitor(Read(Service(fake)))["supportsWrite"],"current must be actual legal level");}
  foreach(bool? active in new bool?[]{false,null}){fake=new Fake();fake.Methods[0].Active=active;monitor=Monitor(Read(Service(fake)));Check(!(bool)monitor["supportsWrite"]&&(string)monitor["unavailableReason"]=="METHOD_NOT_PAIRED","inactive method never grants write");}
  fake=new Fake();fake.Methods[0].InstanceName="display\\PRIVATE-SERIAL-A_0";Check(!(bool)Monitor(Read(Service(fake)))["supportsWrite"],"pairing is exact, not case-fuzzy instance inference");fake=new Fake();fake.Methods=new[]{fake.Methods[0],fake.Methods[0]};Check(!(bool)Monitor(Read(Service(fake)))["supportsWrite"],"duplicate method is ambiguous");fake=new Fake();fake.Monitors=new[]{fake.Monitors[0],fake.Monitors[0]};monitor=Monitor(Read(Service(fake)));Check(!(bool)monitor["supportsWrite"]&&monitor["currentBrightness"]==null&&(string)monitor["unavailableReason"]=="AMBIGUOUS_MONITOR","duplicate brightness instance is deduped and unknown");
  fake=new Fake();fake.Monitors=Enumerable.Repeat(fake.Monitors[0],17).ToArray();Rejected(()=>Read(Service(fake)),"INVALID_PROVIDER_DATA");fake=new Fake();fake.Methods=null;Rejected(()=>Read(Service(fake)),"INVALID_PROVIDER_DATA");
 }
 static void SetFacts(){
  var fake=new Fake();var service=Service(fake);var snapshot=Read(service);var same=service.Handle(Request(snapshot,50));Check(fake.Writes==0&&fake.Reads==2&&fake.MethodReads==2&&(bool)same["alreadyCurrent"]&&(bool)same["readbackConfirmed"]&&!(bool)same["writeAttempted"]&&same["methodReturnCode"]==null,"already-current only performs complete fresh GET and no SET");Rejected(()=>service.Handle(Request(snapshot)),"CAPTURE_EXPIRED");Check(fake.Writes==0,"consumed no-op capture cannot be reused");
  fake=new Fake();service=Service(fake);snapshot=Read(service);var applied=service.Handle(Request(snapshot));Check(fake.Writes==1&&fake.Reads==3&&fake.MethodReads==3&&(bool)applied["readbackConfirmed"]&&(uint)applied["methodReturnCode"]==0&&(int)((Dictionary<string,object>)applied["observed"])["currentBrightness"]==75,"method success plus independent GET confirms exact brightness");Check((int)applied["originalBrightness"]==50,"original current preserved only as evidence, not an automatic restore point");Rejected(()=>service.Handle(Request(snapshot)),"CAPTURE_EXPIRED");Check(fake.Writes==1,"no automatic resend of a consumed transaction");
  foreach(bool changed in new[]{false,true}){fake=new Fake{Code=17};if(!changed)fake.OnSet=f=>{};service=Service(fake);snapshot=Read(service);var result=service.Handle(Request(snapshot));Check(!(bool)result["readbackConfirmed"]&&fake.Writes==1&&(string)result["errorCode"]=="METHOD_FAILED","nonzero method result never becomes claimed application even if external current matches");}
  fake=new Fake{OnSet=f=>{}};service=Service(fake);snapshot=Read(service);var mismatch=service.Handle(Request(snapshot));Check(!(bool)mismatch["readbackConfirmed"]&&(string)mismatch["errorCode"]=="READBACK_MISMATCH","ACK0 alone is not brightness readback");
  fake=new Fake{ThrowSet=true};service=Service(fake);snapshot=Read(service);var error=service.Handle(Request(snapshot));Check(!(bool)error["readbackConfirmed"]&&(bool)error["writeAttempted"]&&(string)error["errorCode"]=="METHOD_EXCEPTION"&&!new JavaScriptSerializer().Serialize(error).Contains("PRIVATE-SERIAL"),"native exception sanitized and uncertain, without retry");
  fake=new Fake{InvalidMethodResult=true};service=Service(fake);snapshot=Read(service);error=service.Handle(Request(snapshot));Check(!(bool)error["readbackConfirmed"]&&error["methodReturnCode"]==null&&(string)error["errorCode"]=="INVALID_METHOD_RESULT"&&fake.Writes==1,"invalid method return preserves unknown completion category even when later getter matches");Check(WindowsBrightnessRules.UnknownMethodCompletion("METHOD_EXCEPTION")&&WindowsBrightnessRules.UnknownMethodCompletion("INVALID_METHOD_RESULT"),"method exception and invalid return are unknown-completion facts");foreach(string status in new[]{"METHOD_FAILED","READBACK_MISMATCH","READBACK_FAILED","READBACK_IDENTITY_CHANGED",null})Check(!WindowsBrightnessRules.UnknownMethodCompletion(status),"readback or completed nonzero method result is not a still-running claim");
  fake=new Fake{ThrowReadAfter=true};service=Service(fake);snapshot=Read(service);error=service.Handle(Request(snapshot));Check(!(bool)error["readbackConfirmed"]&&error["observed"]==null&&(string)error["errorCode"]=="READBACK_FAILED","readback failure clears current evidence");
  fake=new Fake{OnSet=f=>f.Monitors=new BrightnessRawMonitor[0]};service=Service(fake);snapshot=Read(service);error=service.Handle(Request(snapshot));Check(!(bool)error["readbackConfirmed"]&&error["observed"]==null&&(string)error["errorCode"]=="READBACK_IDENTITY_CHANGED","removed monitor cannot be inferred from old state");
  foreach(Action<Fake> change in new Action<Fake>[]{f=>f.Monitors[0].Current=25,f=>f.Methods[0].Active=false,f=>f.Monitors[0].Levels=new[]{0,20,50,75,100},f=>f.Monitors[0].InstanceName="DISPLAY\\other"}){fake=new Fake();service=Service(fake);snapshot=Read(service);change(fake);Rejected(()=>service.Handle(Request(snapshot)),"CURRENT_CHANGED");Check(fake.Writes==0,"fresh topology/caps/current change prevents setter");}
  fake=new Fake();service=Service(fake);snapshot=Read(service);Rejected(()=>service.Handle(Request(snapshot,51)),"UNSUPPORTED_LEVEL");Check(fake.Reads==1&&fake.Writes==0,"not-enumerated percentage never calls driver");
 }
 static void Inputs(){foreach(object value in new object[]{null,"75",75.0,true,-1,101}){var fake=new Fake();var service=Service(fake);var request=Request(Read(service));request["brightness"]=value;Rejected(()=>service.Handle(request),"INVALID_REQUEST");Check(fake.Reads==1&&fake.Writes==0,"illegal input before all further I/O");}
  foreach(string field in new[]{"targetId","sessionToken","readToken","currentFingerprint"}){var fake=new Fake();var service=Service(fake);var request=Request(Read(service));request[field]="bad";Rejected(()=>service.Handle(request),"INVALID_REQUEST");Check(fake.Writes==0,"untrusted identity never reaches setter");}
  foreach(object consent in new object[]{false,"true",1,null}){var fake=new Fake();var service=Service(fake);var request=Request(Read(service));request["experimental"]=consent;Rejected(()=>service.Handle(request),"INVALID_REQUEST");Check(fake.Reads==1&&fake.Writes==0,"only explicit boolean consent accepted");}
  var source=new Fake();var controller=Service(source);var capture=Read(controller);var stale=Request(capture);stale["readToken"]=new string('a',32);Rejected(()=>controller.Handle(stale),"CAPTURE_EXPIRED");var foreign=Service(new Fake());Rejected(()=>foreign.Handle(Request(capture)),"CAPTURE_EXPIRED");Read(controller);Rejected(()=>controller.Handle(Request(capture)),"CAPTURE_EXPIRED");Check(source.Writes==0,"new read replaces every prior capture");
  foreach(long time in new long[]{-1,30001}){long now=0;source=new Fake();controller=Service(source,()=>now);capture=Read(controller);now=time;Rejected(()=>controller.Handle(Request(capture)),"CAPTURE_EXPIRED");Check(source.Reads==1&&source.Writes==0,"expiry/rewind refuses before provider query");}
  long clock=0;source=new Fake();controller=Service(source,()=>clock);capture=Read(controller);source.OnRead=f=>{if(f.Reads==2)clock=30001;};Rejected(()=>controller.Handle(Request(capture)),"CAPTURE_EXPIRED");Check(source.Writes==0,"lease expiry during fresh getter still prevents actual SET");
  foreach(string op in new[]{"restore","calibrate","init","policy","setALS",null}){source=new Fake();controller=Service(source);Rejected(()=>controller.Handle(Map("op",op)),"INVALID_REQUEST");Check(source.Reads==0&&source.Writes==0,"only fixed two operations are exposed");}source=new Fake();controller=Service(source);var extra=Map("op","read","namespace","root\\cimv2");Rejected(()=>controller.Handle(extra),"INVALID_REQUEST");Check(source.Reads==0,"caller cannot select namespace/class");
 }
 static int Main(){try{ReadFacts();SetFacts();Inputs();Console.WriteLine("Windows brightness: "+checks+" pure checks passed; WMI calls 0, hardware writes 0.");return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
